import type { IconNode, IconSource } from "@/lib/icons/svg-icon";
import { renderIconSource } from "@/lib/icons/svg-icon";

/**
 * Canonical list of sports a court can offer. Shared by the admin court form
 * (checkboxes), the home "Sesiones públicas" filter (`SportChip`), the
 * `/mapa` filter chips, and `buildCourtIcon` (`components/map/map-shared.tsx`),
 * which picks the pin glyph from a court's `sports[]` — one sport shows its
 * icon, zero or several fall back to a generic pin. `courts.sports` stores an
 * array of these `key`s.
 *
 * `icon` is the single source of truth for each sport's glyph, rendered both
 * as a React component (`SportIcon`, below) and as a raw SVG string for
 * Leaflet's `divIcon` via `renderIconSource` — so the chip and the map pin
 * always show the exact same artwork. It's one of two kinds:
 * - `stroke`: hand-drawn 24x24 lucide-style paths (futsal) for a sport
 *   without a ready-made icon matching its equipment.
 * - `fill`: a filled silhouette lifted from an svgrepo.com asset (fútbol,
 *   básquet, voleibol, and the tennis-ball glyph shared by tenis/pádel),
 *   own `viewBox`, hardcoded fills stripped so `currentColor` cascades in
 *   from the wrapping `<svg fill="...">`.
 */

