export type SportKey = (typeof SPORTS)[number]["key"];

export const SPORT_CATALOG_KEYS: readonly SportKey[] = SPORTS.map((s) => s.key);

const SPORT_BY_KEY = new Map(SPORTS.map((s) => [s.key, s]));

/** Looks up a sport's label/icon by key; returns undefined for unknown/stale keys. */
export function getSport(key: string) {
  return SPORT_BY_KEY.get(key as SportKey);
}

/**
 * React version of a sport's glyph, built from the same `icon` used for
 * the Leaflet map pins (`renderIconSource`) — so a chip here and a pin on
 * `/mapa` are pixel-identical artwork, not just similar. Renders nothing for
 * an unknown/stale key.
 */
export function SportIcon({
  sport,
  size = 16,
  className,
}: {
  sport: string;
  size?: number;
  className?: string;
}) {
  const entry = getSport(sport);
  if (!entry) return null;
  return (
    <span
      aria-hidden
      className={className}
      style={{ display: "inline-flex", width: size, height: size }}
      dangerouslySetInnerHTML={{ __html: renderIconSource(entry.icon, { size }) }}
    />
  );
}
